//! Hidden decision canaries: known-answer decision items a checker keeps
//! private, sent to contributor pylons through the normal dispatch path.
//!
//! A canary pool is a file of JSON lines, one [`Canary`] each: a NIP-DEC
//! `state` and `questions` and, for every question, the reference
//! probability vector (in the question's option order, as
//! [`crate::verify::probabilities`] reads it) that the pinned model gave on
//! a reference server. The items come from [`crate::items`]' generator
//! under a seed derived from a secret seed file, so the pool cannot be
//! regenerated by anyone without that file, and a model distilled on the
//! public generator's other seeds gains nothing.
//!
//! `openagents pylon canary make --seed-file F --reference URL --count N
//! --out FILE` writes a pool. The gateway (`decisions.canaries`) sends one
//! canary now and then to a contributor pylon as an ordinary decision job
//! from its normal dispatch key, never returns its answer to anyone, and
//! scores it with [`distances`] like a sampled recompute.

use std::collections::BTreeMap;
use std::io::Write;
use std::path::Path;

use serde::{Deserialize, Serialize};
use serde_json::{Map, Value};
use sha2::{Digest, Sha256};

use crate::decide::Decider;
use crate::items;
use crate::verify;

/// The schema tag every canary line carries.
pub const SCHEMA: &str = "openagents.pylon.canary.v1";

/// Question names a canary's one question takes, so a canary's shape is
/// not told apart by a fixed name (real requests name their questions).
const NAMES: &[&str] = &[
    "topic", "intent", "urgent", "fit", "relevant", "route", "severity", "kind", "team", "refund",
    "priority", "answer",
];

/// One known-answer decision item.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
pub struct Canary {
    /// [`SCHEMA`].
    pub v: String,
    /// The pool's own name for the item; never sent to a pylon.
    pub id: String,
    /// The served identity the reference vectors came from
    /// (`clef-flash@sha256:…`).
    pub identity: String,
    /// The decision's `state`.
    pub state: Value,
    /// The decision's `questions`.
    pub questions: Map<String, Value>,
    /// Each question's reference probabilities, in option order.
    pub reference: BTreeMap<String, Vec<f64>>,
}

impl Canary {
    /// The request a pylon receives: `model`, `state`, `questions`, as any
    /// decision.
    #[must_use]
    pub fn body(&self, model: &str) -> Value {
        serde_json::json!({"model": model, "state": self.state, "questions": self.questions})
    }
}

/// The item seed a secret seed file gives: the first eight bytes of the
/// file's SHA-256.
#[must_use]
pub fn seed(secret: &[u8]) -> u64 {
    let digest = Sha256::digest(secret);
    let mut bytes = [0_u8; 8];
    bytes.copy_from_slice(&digest[..8]);
    u64::from_be_bytes(bytes)
}

/// The unanswered canaries for `seed`: the generator's items with their
/// one question renamed. The reference vectors are filled by [`make`].
#[must_use]
pub fn drafts(seed: u64, count: u32) -> Vec<Canary> {
    items::items(seed, count)
        .into_iter()
        .enumerate()
        .map(|(i, item)| {
            let name = NAMES[(seed as usize).wrapping_add(i * 7) % NAMES.len()];
            let mut questions = Map::new();
            questions.insert(name.to_owned(), item.question);
            Canary {
                v: SCHEMA.into(),
                id: nostr::pylon::sha256_hex(item.id.as_bytes())[..16].to_owned(),
                identity: String::new(),
                state: item.state,
                questions,
                reference: BTreeMap::new(),
            }
        })
        .collect()
}

/// Make `count` canaries from `seed`, answering each on `reference` (the
/// pinned model on a reference server).
///
/// # Errors
///
/// When the reference does not answer, refuses an item, or answers one
/// inconsistently.
pub async fn make(seed: u64, reference: &dyn Decider, count: u32) -> Result<Vec<Canary>, String> {
    if !reference.healthy().await {
        return Err("the reference decision server does not answer".into());
    }
    let identity = reference.identity().advertised();
    let mut out = Vec::new();
    for mut canary in drafts(seed, count) {
        let body = reference
            .decide(&canary.state, &canary.questions)
            .await
            .map_err(|refusal| format!("the reference refused an item ({})", refusal.code))?;
        for (id, question) in &canary.questions {
            let p = verify::consistent(question, &body["answers"][id])
                .map_err(|why| format!("the reference answered an item badly: {why}"))?;
            canary.reference.insert(id.clone(), p);
        }
        canary.identity.clone_from(&identity);
        out.push(canary);
    }
    Ok(out)
}

/// Read a pool file.
///
/// # Errors
///
/// When the file cannot be read or a line is not a canary.
pub fn load(path: &Path) -> Result<Vec<Canary>, String> {
    let text = std::fs::read_to_string(path).map_err(|e| format!("{}: {e}", path.display()))?;
    text.lines()
        .filter(|line| !line.trim().is_empty())
        .enumerate()
        .map(|(i, line)| {
            let canary: Canary = serde_json::from_str(line)
                .map_err(|e| format!("{} line {}: {e}", path.display(), i + 1))?;
            if canary.v != SCHEMA {
                return Err(format!(
                    "{} line {}: not a {SCHEMA} line",
                    path.display(),
                    i + 1
                ));
            }
            if canary.questions.keys().ne(canary.reference.keys()) {
                return Err(format!(
                    "{} line {}: every question needs its reference",
                    path.display(),
                    i + 1
                ));
            }
            Ok(canary)
        })
        .collect()
}

/// Write a pool file, readable by its owner only.
///
/// # Errors
///
/// When the file cannot be written.
pub fn write(path: &Path, canaries: &[Canary]) -> Result<(), String> {
    let mut options = std::fs::OpenOptions::new();
    options.create(true).write(true).truncate(true);
    #[cfg(unix)]
    {
        use std::os::unix::fs::OpenOptionsExt;
        options.mode(0o600);
    }
    let mut file = options
        .open(path)
        .map_err(|e| format!("{}: {e}", path.display()))?;
    for canary in canaries {
        let line = serde_json::to_string(canary).map_err(|e| e.to_string())?;
        writeln!(file, "{line}").map_err(|e| format!("{}: {e}", path.display()))?;
    }
    Ok(())
}

/// Each question's distance from its reference ([`verify::distance`]).
///
/// # Errors
///
/// When the answer is missing a question or is inconsistent with its own
/// probabilities ([`verify::consistent`]): a strike.
pub fn distances(canary: &Canary, response: &Value) -> Result<Vec<f64>, String> {
    canary
        .questions
        .iter()
        .map(|(id, question)| {
            let p = verify::consistent(question, &response["answers"][id])?;
            let q = canary
                .reference
                .get(id)
                .ok_or_else(|| format!("no reference for `{id}`"))?;
            Ok(verify::distance(&p, q))
        })
        .collect()
}

#[cfg(test)]
mod tests {
    #![allow(clippy::unwrap_used)]

    use super::*;
    use crate::decide::{Fixed, Identity};

    fn fixed() -> Fixed {
        Fixed {
            identity: Identity {
                model: "clef-flash".into(),
                artifact_digest: Some(format!("sha256:{}", "ab".repeat(32))),
            },
        }
    }

    #[tokio::test]
    async fn a_pool_is_made_written_read_and_scored() {
        let reference = fixed();
        let seed = seed(b"a secret only the checker holds");
        assert_ne!(seed, super::seed(b"another secret"));
        let pool = make(seed, &reference, 6).await.unwrap();
        assert_eq!(pool.len(), 6);
        assert!(
            pool.iter()
                .all(|c| c.identity.starts_with("clef-flash@sha256:"))
        );
        // The question names vary, and none is the generator's fixed `q`.
        assert!(pool.iter().all(|c| !c.questions.contains_key("q")));
        let dir = tempfile::tempdir().unwrap();
        let path = dir.path().join("canaries.jsonl");
        write(&path, &pool).unwrap();
        assert_eq!(load(&path).unwrap(), pool);
        // The same model's answer is at distance 0.
        for canary in &pool {
            let answer = reference
                .decide(&canary.state, &canary.questions)
                .await
                .unwrap();
            assert!(
                distances(canary, &answer)
                    .unwrap()
                    .iter()
                    .all(|d| *d < 1e-9)
            );
        }
        // The same seed makes the same items; the body carries no pool id.
        assert_eq!(drafts(seed, 6)[3].state, pool[3].state);
        assert!(
            !pool[0]
                .body("openagents/decide")
                .to_string()
                .contains(&pool[0].id)
        );
    }

    #[tokio::test]
    async fn a_wrong_or_inconsistent_answer_is_far_or_refused() {
        let reference = fixed();
        let pool = make(seed(b"s"), &reference, 12).await.unwrap();
        let noul = pool
            .iter()
            .find(|c| c.questions.values().any(|q| q["type"] == "noul"))
            .unwrap();
        let id = noul.questions.keys().next().unwrap().clone();
        let mut answer = reference
            .decide(&noul.state, &noul.questions)
            .await
            .unwrap();
        answer["answers"][&id]["noul"] = serde_json::json!(0.01);
        assert!(distances(noul, &answer).unwrap()[0] > verify::CLEF_FLASH.item);
        let choice = pool
            .iter()
            .find(|c| c.questions.values().any(|q| q["type"] == "choice"))
            .unwrap();
        let id = choice.questions.keys().next().unwrap().clone();
        let mut answer = reference
            .decide(&choice.state, &choice.questions)
            .await
            .unwrap();
        // A choice that is not its own most likely option.
        let options: Vec<String> = choice.questions[&id]["criteria"]
            .as_object()
            .unwrap()
            .keys()
            .cloned()
            .collect();
        answer["answers"][&id]["choice"] = serde_json::json!(options[1]);
        assert!(distances(choice, &answer).is_err());
    }
}
